  ('old_prereq_conflict_csci_469', 'requisite', 'CSCI 469 prerequisite: the old course table (p.23) says CSCI 461; the course description (p.42) has no prerequisite line. Omar kept the table reading.', 'Old CS bylaw course tables, p.23; course descriptions, p.42', 'Current value: 009 requires CSCI 461 (the table reading).'),
  ('old_prereq_conflict_csci_479', 'requisite', 'CSCI 479 prerequisite: the old course table (p.22) says CSCI 201; the course description (p.42) has no prerequisite line. Omar kept the table reading.', 'Old CS bylaw course tables, p.22; course descriptions, p.42', 'Current value: 009 requires CSCI 201 (the table reading).'),
  ('old_prereq_conflict_csci_490', 'requisite', 'CSCI 490 prerequisite: the old course table (p.21) says Senior Standing; the course description (p.38) has no prerequisite line. The team replaced Senior Standing with a credit minimum.', 'Old CS bylaw course tables, p.21; course descriptions, p.38', 'Resolved by team decision (BRIEF.md §6, 2026-11-27): 67 passed credits, no standing. Current value: 009 has one credits row for CSCI 490 (group 1, minimum 67) and no standing row.'),
  ('old_sheet_only_csci_112', 'course', 'CSCI 112 Intermediate Programming (3 credits) is an old_cs course taken only from the study-plan workbook (Omar''s decision; the 8 codes of old_sheet_only_codes followed). It is not in the old bylaw PDF; all 8 sheets list it, with the same title and credits, as the prerequisite of CSCI 207. The sheet states none of its flags, and its sheet prerequisite is CSCI 102 (all 8 sheets).', 'CS-StudyPlan_Sep 24.xlsx, sheet Science_Intensive_Media, H8:J8 (all 8 sheets agree)', 'Current value: course row with counts_in_gpa true (team decision (BRIEF.md §6, 2026-11-27)), counts_toward_degree and counts_toward_registration_cap NULL; requisite CSCI 112 -> CSCI 102 from the sheet (K8).'),
  ('old_track_elective_count', 'elective_pool.choose_count', 'The old PDF asks for 6 credit hours of track electives (two 3-credit courses) for the Media and the Big Data track, but every study-plan sheet has one Technical Elective slot (H41), and the term of a second course is not given. Omar''s ruling: keep choose_count 1, the number of courses that one sheet slot takes; adding a second plan slot would invent a semester.', 'Old CS bylaw course tables, p.22 ("Media Informatics Track 6 Credit Hours elective requirements") and p.23 ("Big Data Track 6 Credit Elective requirements")', 'Current value: choose_count 1 on both old pools in 010; their source_reference stays the sheet cell.'),
  ('old_math_001_credits', 'course', 'MATH 001 Pre-Calculus Mathematics has 3 credits in the old course table (p.20) but "(O CH)", that is 0 credits, in its course description (p.33). No winner chosen.', 'Old CS bylaw course tables, p.20; course descriptions, p.33', 'Current value: MATH 001 is not seeded.'),
  ('old_csci_322_credits', 'course.credits', 'CSCI 322 Data Analysis has 3 credits in the old course table (p.21) but 4 in its course description (p.38) and in the sample study plan (p.28).', 'Old CS bylaw course tables, p.21; course descriptions, p.38; sample study plan, p.28', 'Current value: 3 credits (the table; keeps the 135-credit total).'),
  ('old_csci_490_credits', 'course.credits', 'CSCI 490 Industrial/Research Training has 2 credits in the old course table (p.21) and the sample study plan (p.28) but 1 in its course description (p.38).', 'Old CS bylaw course tables, p.21; course descriptions, p.38; sample study plan, p.28', 'Current value: 2 credits (the table).'),
  ('old_csci_105_vs_csci_201', 'course', 'The sample study plan (pp.27-28) uses CSCI 105 Introduction to Programming; the course table has CSCI 201 Introduction to Programming (p.20). No source says they are the same course.', 'Old CS bylaw sample study plan, pp.27-28; course tables, p.20', 'Current value: CSCI 201 is seeded; CSCI 105 is not.'),
  ('old_csci_221l_lab', 'course', 'The sample study plan (p.27) splits Logic Design into CSCI 221 (3 credits) and CSCI 221L Logic Design Lab (1 credit), and CSCI 221L has a course description (p.37); the course table has one CSCI 221 Logic Design with 4 credits (p.20).', 'Old CS bylaw sample study plan, p.27; course descriptions, p.37; course tables, p.20', 'Current value: CSCI 221 with 4 credits; CSCI 221L is not seeded.'),
  ('old_math_302_unknown', 'course', 'The Big Data sample study plan (p.29) names MATH 302 as a prerequisite of CSCI 467; MATH 302 is not in the old course tables (pp.19-23).', 'Old CS bylaw sample study plan, p.29', 'Current value: MATH 302 is not seeded.'),
  ('old_sheet_only_codes', 'course', 'Eight more codes appear only in the study-plan workbook, not in the old bylaw PDF: CSCI 102, CSCI 208, CSCI 305, ECEN 101C, ENGL 001, MATH 100, PHYS 101C, and SSCI 105 (for SSCI 105 see also project_management_code). ENGL 001 and MATH 100 are on 4 sheets, the others on all 8.', 'CS-StudyPlan_Sep 24.xlsx, sheet Science_Intensive_Media: ENGL 001 B6, MATH 100 B7 ("Math 100"), CSCI 102 B8, ECEN 101C B16, PHYS 101C H6, CSCI 208 H18, CSCI 305 H28, SSCI 105 H42', 'Current value: these 8 rows exist as old_cs courses (Omar''s decision, 2026-10-15); they are not in the bylaw course table, and the sheet is the source (code, title, and credits from the cited cell). ENGL 001 and MATH 100: false / false / true. The other six: counts_in_gpa true (team decision (BRIEF.md §6, 2026-11-27)), counts_toward_degree and counts_toward_registration_cap NULL.'),
  ('old_or_concurrent', 'requisite', 'The schema has no co-requisite type. "Or concurrent" appears in the old course table for CSCI 221 (p.20) and CSCI 495 (p.21), and in the course descriptions of ECEN 101 and CSCI 205 (p.36), CSCI 304 (p.37), and CSCI 457 (p.40).', 'Old CS bylaw course tables, pp.20-21; course descriptions, pp.36-37 and p.40', 'Current value: no requisite row for CSCI 221; CSCI 495 has only the team''s 100-credit minimum (its "or concurrent" rule is replaced, see old_core_course_count); ECEN 101, CSCI 205, CSCI 304, and CSCI 457 keep the table reading.'),
  ('old_school_certificate_placement', 'requisite', 'Twelve old courses require "Thanaweya Amma or equivalent" (HUMA 101, HUMA 102, HUMA 103, SSCI 101, SSCI 102, SSCI 103, COMM 401, NSCI 102, and PHYS 101 on p.19; MATH 111, CSCI 101, and CSCI 201 on p.20), and ENGL 101 requires "English 101 Placement" (p.19). Seed 001 has no old placement row for either.', 'Old CS bylaw course tables, pp.19-20', 'Current value: no placement requisite for these 13 courses. COMM 401 has a 67-credit minimum (team decision (BRIEF.md §6, 2026-11-27)); the 12 others have no requisite row.'),
  ('old_core_course_count', 'requisite', 'CSCI 495 Senior Project I requires "Completion of 8 core courses Or concurrent" (p.21). The schema has no place for a count of completed courses; the team replaced the rule with a credit minimum.', 'Old CS bylaw course tables, p.21', 'Resolved by team decision (BRIEF.md §6, 2026-11-27): CSCI 495 and CSCI 496 need 100 passed credits. Current value: 009 has a credits row (group 1, minimum 100) for CSCI 495 and for CSCI 496; CSCI 496 also keeps CSCI 495 in group 1 (both apply).'),
  ('new_school_certificate_prereq', 'requisite', 'Ten 2025 courses require "High School certificate or equivalent" (HUMA 103, HUMA 111, HUMA 203, SSCI 101, SSCI 102, SSCI 203, SSCI 204, and SSCI 205 on p.24; CSC 101 and CSC 102 on p.25), and MATH 120 requires "High School certificate (Science Section)" (p.24). Seed 001 has only the high_school_math placement (Math Section).', '2025 bylaw Art. 36, pp.24-25', 'Current value: no requisite row for these 11 courses.'),
  ('new_engl_univ_regulations', 'requisite', 'ENGL 001 and ENGL 002 require "According to Univ. regulations" (p.24); the regulation is not named.', '2025 bylaw Art. 36, p.24', 'Current value: no requisite row for ENGL 001 or ENGL 002.'),
  ('new_csc_493_87_credits', 'requisite', 'CSC 493 Senior Project I requires "Completing 87 Credit Hours or more" (p.28). The database now stores a credits requisite with min_credits_passed 87, independently of the standing bands (27 / 62 / 96). Backend B must evaluate this new type against completed credits at the information cutoff.', '2025 bylaw Art. 36, p.28', 'Current value: 007 seeds one group-1 credits requisite for CSC 493 with minimum 87. Database support is implemented; eligibility-consumer integration must be confirmed before this gap is marked resolved.'),
  ('new_training_project_credits', 'course.credits', 'The p.28 heading says "Industrial/Research Training and Graduation Project (10 credit hours)", but its 4 rows (CSC 291, CSC 391, CSC 493, CSC 494, 3 credits each) add up to 12, and the Article 36 summary table gives Training 6 and Graduation Projects 6 (p.23).', '2025 bylaw Art. 36, p.23 and p.28', 'Current value: 3 credits each (the rows).'),
  ('new_training_project_components', 'course_component', 'The p.28 table gives weekly student workload and number of weeks for CSC 291, CSC 391, CSC 493, and CSC 494, not Lecture, Tutorial, or Lab hours.', '2025 bylaw Art. 36, p.28', 'Current value: no component rows for these 4 courses.'),
  ('old_general_track_elective_pool', 'elective_pool', 'The old general-track elective list (CSCI 451, 452, 455, 456, 457, 458, 461, 462, 464, 465, 467, 471, 472, 475, and 479) asks for 12 credit hours; all 15 have 3 credits, so that is four courses. There is no general-track row and no plan slot for it.', 'Old CS bylaw course tables, pp.21-22; elective list, p.30', 'Current value: no pool.'),
  ('old_gen_ed_elective_pool', 'elective_pool', 'The old general-education elective "NSCI, SSCI, or HUMA" (3 credits) has no course list: the description says "an additional course to be chosen from one of the above three categories".', 'Old CS bylaw course tables, p.19; course descriptions, p.34; sample study plans, pp.28-29 ("XXXX XXX"); CS-StudyPlan_Sep 24.xlsx, "XXXX XXX" slots (H43, H38, or B43)', 'Current value: no pool, so the 8 "XXXX XXX" sheet boxes get no plan_slot.'),
  ('new_other_programs_not_seeded', 'course, requisite, elective_pool', 'The 2025 bylaw PDF also has the AI, BMD, and CSEC programs with their own course tables and elective pools (for example pp.38-40, 46-49, and 58-61). Only Article 36 (the CS program) is seeded: courses the other programs share with Article 36 exist, but their other courses and their elective pools are not seeded, and their tables were not read for prerequisites. elective_pool has no program column (the CS and BMD Social Sciences pools differ: BMD selects 4 credit hours, p.47).', '2025 bylaw, pp.38-40, 46-49, 58-61', 'Current value: only the Article 36 courses, requisites, and pools are seeded.')
)
INSERT INTO data_gap (
  category,
  description,
  affected_entity,
  status,
  source_reference,
  notes
)
SELECT
  v.category,
  v.description,
  v.affected_entity,
  'open',
  v.source_reference,
  v.notes
FROM v
WHERE NOT EXISTS (
  SELECT 1 FROM data_gap d WHERE d.category = v.category
);

-- check: 28 conflict, 2 required, 18 extra Part B data gaps, and no category twice in data_gap
DO $$
DECLARE
  conflict_count integer;
  required_count integer;
  extra_count integer;
  duplicate_count integer;
BEGIN
  SELECT count(*) INTO conflict_count FROM data_gap d WHERE left(d.category, 20) = 'old_prereq_conflict_';
  SELECT count(*) INTO required_count FROM data_gap d WHERE d.category IN ('old_sheet_only_csci_112', 'old_track_elective_count');
  SELECT count(*) INTO extra_count FROM data_gap d WHERE d.category IN ('old_math_001_credits', 'old_csci_322_credits', 'old_csci_490_credits', 'old_csci_105_vs_csci_201', 'old_csci_221l_lab', 'old_math_302_unknown', 'old_sheet_only_codes', 'old_or_concurrent', 'old_school_certificate_placement', 'old_core_course_count', 'new_school_certificate_prereq', 'new_engl_univ_regulations', 'new_csc_493_87_credits', 'new_training_project_credits', 'new_training_project_components', 'old_general_track_elective_pool', 'old_gen_ed_elective_pool', 'new_other_programs_not_seeded');

  SELECT count(*) INTO duplicate_count
  FROM (
    SELECT 1
    FROM data_gap d
    GROUP BY d.category
    HAVING count(*) > 1
  ) x;

  IF conflict_count <> 28 THEN
    RAISE EXCEPTION 'Expected 28 conflict data gaps, found %', conflict_count;
  END IF;
  IF required_count <> 2 THEN
    RAISE EXCEPTION 'Expected 2 required data gaps, found %', required_count;
  END IF;
  IF extra_count <> 18 THEN
    RAISE EXCEPTION 'Expected 18 extra data gaps, found %', extra_count;
  END IF;

  IF duplicate_count > 0 THEN
    RAISE EXCEPTION '% data_gap categories occur more than once', duplicate_count;
  END IF;
END $$;
